import sys, json, random, subprocess, time; sys.path.insert(0,'/workspace/dev'); sys.path.insert(0,'/workspace')
from harness import run as runbatch
from wire import envelope, stream, crypto, datagram, trace, v as vmin
import invariants
def consistent(off,n): return bytes(((off+i)*7+3)&0xff for i in range(n))
def vw(value):
    ws=[w for w in (1,2,4,8) if value < 2**(8*w-2)]
    return vmin(value, random.choice(ws))

def gen(seed):
    random.seed(seed)
    corrupt = random.random()<0.5
    traces=[]
    ncids={}
    for t in range(6):
        events=[]
        if random.random()<0.8: events.append({'keys':random.sample(['I','H','A'],random.randrange(1,4))})
        pn={'I':0,'H':0,'A':0}; cur=0
        local=[bytes([0xa0+i]*random.choice([1,2])).hex() for i in range(random.randrange(1,4))]
        for e in range(50):
            if random.random()<0.1:
                events.append({'keys':random.sample(['I','H','A'],random.randrange(0,4))}); continue
            lvl=random.choice(['A','A','I','H'])
            bodies=[]
            for f in range(random.randrange(1,5)):
                k=random.randrange(12)
                rid=random.choice([0,4,8]); uid=random.choice([2,6]); sid=random.choice([1,5]); suid=random.choice([3,7])
                if k==0:
                    hasoff=random.random()<0.8
                    off=random.randrange(0,40)*4 if hasoff else 0; n=random.randrange(0,20)
                    fin=random.random()<0.1
                    bodies.append(stream(random.choice([rid,uid,sid]),off,consistent(off,n),fin=fin,offset=hasoff,length=True))
                elif k==1:
                    off=random.randrange(0,40)*4; n=random.randrange(0,20); bodies.append(crypto(off,consistent(off,n)))
                elif k==2:
                    lg=random.randrange(0,200); bodies.append(bytes([random.choice([2,3])])+vw(lg)+vw(random.randrange(4))+vw(0)+vw(random.randrange(0,lg+1))+(vw(1)+vw(2)+vw(3) if random.random()<0.5 else b''))
                elif k==3: bodies.append(b'\x00'*random.randrange(1,3)+b'\x01')
                elif k==4: bodies.append(b'\x10'+vw(random.randrange(10**6)))
                elif k==5: bodies.append(b'\x15'+vw(random.choice([rid,uid,sid]))+vw(0))
                elif k==6: bodies.append(b'\x11'+vw(random.choice([rid,sid,suid]))+vw(random.randrange(10**4)))
                elif k==7:
                    sq=random.randrange(1,4); ncids[sq]=bytes([0xd0+sq])
                    bodies.append(b'\x18'+vw(sq)+vw(0)+b'\x01'+ncids[sq]+b'\x22'*16)
                elif k==8: bodies.append(b'\x19'+vw(random.randrange(0,len(local))))
                elif k==9: bodies.append(random.choice([b'\x14'+vw(3),b'\x16'+vw(2),b'\x17'+vw(1),b'\x1a'+b'12345678',b'\x1b'+b'87654321',b'\x31'+vw(2)+b'xy',b'\x30'+b'tail']))
                elif k==10: bodies.append(b'\x05'+vw(random.choice([rid,sid,suid]))+vw(3))
                else: bodies.append(b'\x04'+vw(random.choice([rid,uid,sid]))+vw(7)+vw(10**9))
            if random.random()<0.05: bodies.append(b'\x1d'+vw(0)+vw(0))
            if lvl!='A':
                bodies=[b for b in bodies if b[:1] in (b'\x00',b'\x01',b'\x02',b'\x03',b'\x06')] or [b'\x01']
            body=b''.join(bodies)
            if corrupt and random.random()<0.25 and len(body)>2:
                i=random.randrange(len(body)); body=body[:i]+bytes([random.randrange(256)])+body[i+1:]
            g=cur; phase=g&1
            if lvl=='A' and random.random()<0.2: g=cur+1; phase=g&1
            cid=random.choice([bytes.fromhex(x) for x in local])
            w=envelope(lvl,pn[lvl],body,width=random.choice([1,2,4]),cid=cid,phase=phase)
            pn[lvl]+=1
            if lvl=='A' and g==cur+1: cur=g
            ann=g if random.random()<0.85 else random.choice([None,0,5])
            events.append(datagram(w,auth=(ann,)*2))
        recv={k:(random.choice([None,0,3,2**62-1]) if random.random()<0.3 else None) for k in 'IHA'}
        traces.append(trace(events, connection=random.choice([2**62-1,500]), stream_credit=random.choice([2**62-1,60]),
                            bidi=random.choice([2**60,2]), uni=random.choice([2**60,2]), cids=random.choice([4,2,3]),
                            local_bidi=2, local_uni=2, local_cids=tuple(local), received=recv))
    return {'traces':traces}

bad=0
for seed in range(int(sys.argv[1]), int(sys.argv[2])):
    batch=gen(seed)
    data=json.dumps(batch).encode()
    p=subprocess.run(['python3','/workspace/run.py','/workspace/tmp/classes'],input=data,capture_output=True)
    if p.returncode!=0:
        print('seed',seed,'NONZERO EXIT',p.returncode,p.stderr.decode()[:500]); bad+=1; continue
    try: out=json.loads(p.stdout)
    except Exception as ex: print('seed',seed,'BAD JSON',ex,p.stdout[:200]); bad+=1; continue
    errs=[]
    invariants.check(batch,out,errs)
    if errs:
        bad+=1
        print('seed',seed,'INVARIANTS',errs[:6])
print('done, failures:',bad)
